components.css:
.ds-study-focus{font-family:LifeSans,Arial,sans-serif;font-size:14px;color:var(--ink,#303b32)}.ds-study-focus p,.ds-study-focus h2,.ds-study-focus h3{margin:0}.ds-study-focus p{line-height:1.7}.ds-study-focus h2{font-family:var(--serif,Chronicle,Georgia,serif);font-weight:600}.ds-study-focus svg{flex-shrink:0}.ds-study-focus{margin-top: 19px;
  padding-top: 16px;
  border-top: 1px dashed var(--line);}
.ds-study-focus label{display: block;
  font-size: 11px;
  color: var(--muted);
  margin-bottom: 7px;}
.ds-study-focus select{width: 100%;
  min-height: 37px;
  background: #fdfcf8;
  border: 1px solid #d1d8c5;
  border-radius: 5px;
  padding: 7px 9px;
  font-size: 12px;}
.ds-study-unlock,
.ds-known-spells p{font-size: 11px;
  color: var(--muted);
  line-height: 1.7;}
.ds-next-spell{display: flex;
  align-items: flex-start;
  gap: 7px;
  margin-top: 13px;
  color: var(--green);
  font-size: 11px;}
.ds-next-spell > svg{margin-top: 3px;}
.ds-next-spell strong{font-weight: 500;}
.ds-next-spell small{display: block;
  color: var(--muted);
  font-size: 10px;
  margin-top: 3px;}
.ds-known-spells{margin-top: 12px;
  font-size: 11px;
  color: var(--green);}
.ds-known-spells summary{cursor: pointer;
  padding: 5px 0;}
.ds-known-spells summary:focus-visible{outline: 2px solid var(--gold);
  outline-offset: 3px;}
.ds-known-spells ul{padding: 3px 0 0;
  list-style: none;
  margin: 0;}
.ds-known-spells li{display: flex;
  align-items: center;
  gap: 6px;
  padding: 5px 0;}
.ds-known-spells p{margin-top: 7px;}.ds-study-focus label{display:block;margin-bottom:7px}.ds-study-focus select{color:var(--ink,#303b32);font-family:inherit}.ds-study-focus select:focus-visible{outline:2px solid #8c7039;outline-offset:4px}.ds-study-focus .ds-next-spell{margin-top:13px}.ds-study-focus .ds-known-spells p{margin-top:7px}

.ds-career-section{font-family:LifeSans,Arial,sans-serif;font-size:14px;color:var(--ink,#303b32)}.ds-career-section p,.ds-career-section h2,.ds-career-section h3{margin:0}.ds-career-section p{line-height:1.7}.ds-career-section h2{font-family:var(--serif,Chronicle,Georgia,serif);font-weight:600}.ds-career-section svg{flex-shrink:0}.ds-career-section > h2 > svg{color: var(--green);}
.ds-career-title{display: flex;
  align-items: flex-start;
  gap: 10px;}
.ds-career-icon{width: 31px;
  min-height: 35px;
  background: #e8e9dc;
  display: flex;
  align-items: center;
  justify-content: center;
  border-radius: 5px;
  color: #697549;}
.ds-career-title h3{font-size: 13px;
  line-height: 1.5;
  font-weight: 500;}
.ds-career-title p{font-size: 10px;
  line-height: 1.6;
  color: var(--muted);
  margin-top: 4px;}
.ds-career-income{display: flex;
  align-items: baseline;
  justify-content: space-between;
  flex-wrap: wrap;
  gap: 5px;
  margin-top: 17px;
  font-size: 11px;}
.ds-career-income strong{font-weight: 500;
  color: #6c603a;}
.ds-career-income small{flex-basis: 100%;
  font-size: 9px;
  color: var(--muted);
  line-height: 1.6;}
.ds-promotion-plan{padding-top: 16px;
  margin-top: 16px;
  border-top: 1px dashed var(--line);}
.ds-promotion-plan h4{font-size: 11px;
  font-weight: 500;
  margin: 0 0 10px;
  line-height: 1.6;}
.ds-promotion-plan ul{list-style: none;
  margin: 12px 0;
  padding: 0;
  display: grid;
  gap: 9px;}
.ds-promotion-plan li{display: flex;
  align-items: flex-start;
  gap: 7px;
  color: var(--muted);
  font-size: 11px;
  line-height: 1.6;}
.ds-promotion-plan li > svg{margin-top: 4px;}
.ds-promotion-plan li small{display: block;
  font-size: 10px;}
.ds-promotion-plan li.ds-met{color: var(--green);}
.ds-promotion-plan p,
.ds-career-established{font-size: 11px;
  line-height: 1.8;
  color: var(--muted);}
.ds-career-established{margin-top: 15px;}.ds-career-section{border-bottom:1px solid var(--line,#dedfd3);padding-bottom:24px;margin-bottom:24px}.ds-career-section>h2{font-size:23px;line-height:1.2;margin-bottom:19px}.ds-career-title p{margin-top:4px}.ds-skill-progress{height:3px;background:#e1e4d6;margin-top:8px;border-radius:3px;overflow:hidden}.ds-skill-progress>span{display:block;height:100%;background:#a5b18a}

.ds-spellbook{font-family:LifeSans,Arial,sans-serif;font-size:14px;color:var(--ink,#303b32)}.ds-spellbook p,.ds-spellbook h2,.ds-spellbook h3{margin:0}.ds-spellbook p{line-height:1.7}.ds-spellbook h2{font-family:var(--serif,Chronicle,Georgia,serif);font-weight:600}.ds-spellbook svg{flex-shrink:0}.ds-spellbook{padding-top: 26px;
  margin-top: 29px;
  border-top: 1px solid var(--line);}
.ds-spellbook > h2{font-size: 29px;}
.ds-spellbook > p{color: var(--muted);
  font-size: 12px;
  max-width: 65ch;
  margin-top: 10px;}
.ds-spellbook-studies{margin-top: 22px;}
.ds-spellbook-studies > article{padding: 19px 0 22px;
  border-bottom: 1px solid var(--line);}
.ds-spellbook-studies > article.ds-current-study{background: #edf0e4;
  border-radius: 6px;
  padding: 18px;
  margin-bottom: 5px;
  border: 0;}
.ds-spellbook-studies header{display: flex;
  align-items: flex-start;
  gap: 10px;
  color: var(--green);}
.ds-spellbook-studies header > svg{margin-top: 4px;}
.ds-spellbook-studies h3{font-family: var(--serif);
  font-size: 25px;
  font-weight: 600;}
.ds-spellbook-studies header p{font-size: 11px;
  color: var(--muted);
  margin-top: 4px;}
.ds-school-description{margin-top: 11px;
  font-size: 12px;
  color: var(--muted);}
.ds-spellbook-studies ul{margin: 15px 0 0;
  padding: 0;
  list-style: none;}
.ds-spellbook-studies li{display: flex;
  align-items: flex-start;
  gap: 8px;
  padding: 6px 0;
  color: var(--green);}
.ds-spellbook-studies li > svg{margin-top: 3px;}
.ds-spellbook-studies li strong{display: block;
  font-size: 12px;
  font-weight: 500;}
.ds-spellbook-studies li small{display: block;
  font-size: 11px;
  color: var(--muted);
  line-height: 1.7;
  margin-top: 4px;}
.ds-unwritten-spells{color: var(--muted);
  font-size: 11px;
  margin-top: 13px;}
.ds-spellbook-next{display: flex;
  align-items: flex-start;
  gap: 7px;
  padding-top: 12px;
  margin-top: 13px;
  color: var(--green);}
.ds-spellbook-next > svg{margin-top: 4px;}
.ds-spellbook-next p{font-size: 11px;}
.ds-spellbook-next span{display: block;
  color: var(--muted);
  font-size: 10px;
  margin-top: 3px;}.ds-spellbook>p{margin-top:10px}.ds-spellbook-studies header p{margin-top:4px}.ds-spellbook-studies .ds-school-description{margin-top:11px}@media(max-width:650px){.ds-spellbook>h2{font-size:27px}.ds-spellbook-studies h3{font-size:24px}}
